#include <iostream>
#include <string>
#include <vector>
#include <algorithm>

int main() {
    int n;
    std::cin >> n;
    std::string st;
    std::cin >> st;

    int maxLength = 0, countBrackets = 0;
    std::string sb, sb2;

    for (int i = 0; i < n; i++) {
        if (st[i] == '(') {
            sb += "_";
            i++;
            while (i < n && st[i] != ')') {
                sb2 += st[i];
                i++;
            }
            sb2 += "_";
        } else {
            sb += st[i];
        }
    }

    std::vector<std::string> parts;
    size_t start = 0, end;
    while ((end = sb.find('_', start)) != std::string::npos) {
        parts.push_back(sb.substr(start, end - start));
        start = end + 1;
    }
    if (start < sb.size()) {
        parts.push_back(sb.substr(start));
    }

    for (const auto& part : parts) {
        maxLength = std::max(maxLength, static_cast<int>(part.length()));
    }

    std::vector<std::string> bracketParts;
    start = 0;
    while ((end = sb2.find('_', start)) != std::string::npos) {
        std::string p = sb2.substr(start, end - start);
        if (!p.empty()) {
            countBrackets++;
        }
        start = end + 1;
    }
    // Check for last part if no trailing underscore
    if (start < sb2.size()) {
        if (!sb2.substr(start).empty()) {
            countBrackets++;
        }
    }

    std::cout << maxLength << " " << countBrackets << std::endl;
    return 0;
}
